const fillCardFromOrder=$('fillByOrderBtn').onclick;$('fillByOrderBtn').onclick=()=>{const requestedOrder=$('orderNumber').value.trim();fillCardFromOrder();if(!requestedOrder)return;const o=current();o.dbAdministrator=o.dbAdministrator||dictionaries.dbAdmins[0];o.sections=[{order:'1',name:'Основной раздел',description:'Данные получены из приказа',service:'ОС'}];o.loops=[{number:'1',section:'1',name:'Входная дверь',description:'Магнитоконтактный извещатель',type:'Охранный'},{number:'2',section:'1',name:'Объём помещения',description:'Датчик движения',type:'Охранный'}];renderEditor();};
