function setAuthorizedAdmin(account){document.querySelector('.admin-user small').textContent=account.name;let logout=document.querySelector('.admin-logout');if(!logout){logout=document.createElement('button');logout.type='button';logout.className='admin-logout';logout.textContent='Выйти';logout.onclick=()=>{sessionStorage.removeItem('neva-db-admin');location.reload();};document.querySelector('.admin-user').after(logout);}}
function initAdminAuthorization(){const saved=sessionStorage.getItem('neva-db-admin'),account=dbAdminAccounts.find(a=>a.login===saved);if(account){setAuthorizedAdmin(account);return;}const overlay=document.createElement('div');overlay.className='admin-auth';overlay.innerHTML='<form class="admin-auth-card"><h1>Вход для администратора БД</h1><p>Введите фамилию и пароль учётной записи</p><label>Логин<input name="login" autocomplete="username" autofocus></label><label>Пароль<input name="password" type="password" autocomplete="current-password"></label><p class="admin-auth-error" role="alert"></p><button type="submit">Войти</button></form>';document.body.append(overlay);const form=overlay.querySelector('form'),error=overlay.querySelector('.admin-auth-error');form.onsubmit=e=>{e.preventDefault();const login=form.elements.login.value.trim().toLocaleLowerCase('ru-RU'),password=form.elements.password.value,found=dbAdminAccounts.find(a=>a.login.toLocaleLowerCase('ru-RU')===login);if(!found||password!=='123'){error.textContent='Неверная фамилия или пароль';return;}sessionStorage.setItem('neva-db-admin',found.login);setAuthorizedAdmin(found);overlay.remove();};}
initAdminAuthorization();
document.querySelectorAll('#categoryFilter,select[name="category"]').forEach(select=>{const selected=select.id==='categoryFilter'?select.value:(current()?.category||'');if(![...select.options].some(option=>option.value==='1')){const option=new Option('1','1');const firstNumber=[...select.options].find(item=>item.value==='2');select.insertBefore(option,firstNumber||null);}select.value=selected;});
const monitoringSystems=['Анапа Андромеда','Армавир Андромеда','Армавир Феникс','Евпатория Феникс','Краснодар Андромеда','Краснодар Мираж','Краснодар Мираж Бастион','Краснодар Феникс','Невинномысск Феникс','Ростов Андромеда','Ставрополь Андромеда','Ставрополь Феникс'],pcoDirectory=['Краснодар','Армавир','Ставрополь','Анапа','Евпатория','Майкоп','Ростов'];
function systemFamily(value){value=String(value||'');return value==='A'||value.includes('Андромеда')?'A':value==='MK'||value.includes('Мираж')?'MK':'F';}function normalizeSystem(value,pco){if(monitoringSystems.includes(value))return value;const family=systemFamily(value),kind=family==='A'?'Андромеда':family==='MK'?'Мираж':'Феникс',candidate=`${pco} ${kind}`;return monitoringSystems.includes(candidate)?candidate:(monitoringSystems.find(item=>item.endsWith(kind))||'');}function stationPrefix(pco,system){const prefixes={'Анапа Андромеда':'AA','Армавир Андромеда':'AA','Армавир Феникс':'AF','Евпатория Феникс':'EF','Краснодар Андромеда':'KA','Краснодар Мираж':'KM','Краснодар Мираж Бастион':'KMB','Краснодар Феникс':'KF','Невинномысск Феникс':'NF','Ростов Андромеда':'RA','Ставрополь Андромеда':'SA','Ставрополь Феникс':'SF'};return prefixes[system]||(systemFamily(system)==='A'?'A':systemFamily(system)==='MK'?'KM':'F');}
objects.forEach(object=>{const oldPco=String(object.pco||''),city=monitoringSystems.includes(oldPco)?oldPco.split(' ')[0]:oldPco;object.pco=pcoDirectory.includes(city)?city:'';object.system=normalizeSystem(object.system,object.pco);const raw=String(object.number||'').toUpperCase();object.number=/^\d+$/.test(raw)?stationPrefix(object.pco,object.system)+raw:raw;});const stationSelect=form.elements.pco,systemSelect=form.elements.system,pultInput=form.elements.number,emptySelectOption='<option value="" hidden disabled></option>';stationSelect.innerHTML=emptySelectOption+pcoDirectory.map(value=>`<option>${value}</option>`).join('');systemSelect.innerHTML=emptySelectOption+monitoringSystems.map(value=>`<option>${value}</option>`).join('');pultInput.inputMode='text';pultInput.maxLength=10;pultInput.autocapitalize='characters';renderList();renderEditor();
const fillCardWithStation=$('fillByOrderBtn').onclick;$('fillByOrderBtn').onclick=()=>{const requested=$('orderNumber').value.trim();fillCardWithStation();if(!requested)return;const object=current();object.pco=pcoDirectory.includes(object.pco)?object.pco:'Краснодар';object.system=normalizeSystem(object.system,object.pco)||'Краснодар Феникс';const digits=String(object.number||'').replace(/\D/g,'');object.number=stationPrefix(object.pco,object.system)+digits;renderEditor();};
